import React, { useEffect, useRef, useState } from "react";
import CanvasJSReact from "@canvasjs/react-charts";

const { CanvasJSChart } = CanvasJSReact;

const BarChart = () => {
  const chartRef = useRef(null);
  const [chartData, setChartData] = useState(null);

  useEffect(() => {
    const fetchData = async () => {
      try {
        const response = await fetch("http://localhost:5206/api/BloodRL/predict");
        if (response.ok) {
          const data = await response.json();
          setChartData(data);
          console.log(data);
        } else {
          console.error("Failed to fetch data:", response.status, response.statusText);
        }
      } catch (error) {
        console.error("An error occurred while fetching data:", error);
      }
    };

    fetchData();
  }, []);

  return (
    <div>
      {chartData &&
        Object.entries(chartData).map(([bloodGroup, hospitalData]) => (
          <div key={bloodGroup} className="hospital-chart">
            <h3>{bloodGroup} Blood Group</h3>
            <CanvasJSChart
              options={{
                animationEnabled: true,
                theme: "dark2",
                title: {
                  text: "Predicted Blood Availability",
                },
                axisY: {
                  title: "Predicted Availability",
                  scaleBreaks: {
                    autoCalculate: true,
                    type: "wavy",
                    lineColor: "white",
                  },
                },
                data: [
                  {
                    type: "column",
                    indexLabel: "{y}",
                    indexLabelFontColor: "white",
                    dataPoints: Object.values(hospitalData).map((item) => ({
                      label: item.hospitalName,
                      y: item.predictedAvailability,
                    })),
                  },
                ],
              }}
            />
          </div>
        ))}
    </div>
  );
};

export default BarChart;
